package com.pulsepay.auth;
import com.pulsepay.common.ApiException; import com.pulsepay.security.*; import java.security.MessageDigest; import java.sql.Timestamp; import java.time.*; import java.util.*; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController {
 private final JdbcTemplate db; private final PasswordEncoder passwords; private final TokenService tokens;
 public AuthController(JdbcTemplate db,PasswordEncoder passwords,TokenService tokens){this.db=db;this.passwords=passwords;this.tokens=tokens;}
 record Register(String email,String password,String legalName,String displayName){} record Login(String email,String password){} record Refresh(String refreshToken){}
 @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) @Transactional public Map<String,Object> register(@RequestBody Register r){if(r.email()==null||!r.email().contains("@")||!strongPassword(r.password()))throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_REGISTRATION","Use a valid email and a 12+ character password with uppercase, lowercase, and a number."); UUID u=UUID.randomUUID(),m=UUID.randomUUID(); try{db.update("insert into users(id,email,password_hash,role)values(?,?,?,'MERCHANT')",u,r.email().toLowerCase(),passwords.encode(r.password()));db.update("insert into merchants(id,legal_name,display_name)values(?,?,?)",m,required(r.legalName()),required(r.displayName()));db.update("insert into merchant_memberships(merchant_id,user_id)values(?,?)",m,u);}catch(Exception e){throw new ApiException(HttpStatus.CONFLICT,"EMAIL_IN_USE","An account already uses this email.");}audit(u,m,"merchant.registered","merchant",m);return session(new MerchantPrincipal(u,m,"MERCHANT"));}
 @PostMapping("/login") public Map<String,Object> login(@RequestBody Login r){var rows=db.query("select u.id uid,m.id mid,u.password_hash,u.role from users u join merchant_memberships mm on mm.user_id=u.id join merchants m on m.id=mm.merchant_id where u.email=? and u.enabled=true",(rs,i)->Map.of("uid",UUID.fromString(rs.getString("uid")),"mid",UUID.fromString(rs.getString("mid")),"hash",rs.getString("password_hash"),"role",rs.getString("role")),r.email().toLowerCase());if(rows.isEmpty()||!passwords.matches(r.password(),(String)rows.getFirst().get("hash")))throw new ApiException(HttpStatus.UNAUTHORIZED,"INVALID_CREDENTIALS","Invalid email or password.");var x=rows.getFirst();audit((UUID)x.get("uid"),(UUID)x.get("mid"),"merchant.login","user",(UUID)x.get("uid"));return session(new MerchantPrincipal((UUID)x.get("uid"),(UUID)x.get("mid"),(String)x.get("role")));}
 @PostMapping("/refresh") public Map<String,Object> refresh(@RequestBody Refresh r){String h=sha(r.refreshToken());var rows=db.query("select rt.user_id,mm.merchant_id,u.role from refresh_tokens rt join users u on u.id=rt.user_id join merchant_memberships mm on mm.user_id=u.id where rt.token_hash=? and rt.revoked_at is null and rt.expires_at>now()",(rs,i)->new MerchantPrincipal(UUID.fromString(rs.getString(1)),UUID.fromString(rs.getString(2)),rs.getString(3)),h);if(rows.isEmpty())throw new ApiException(HttpStatus.UNAUTHORIZED,"INVALID_REFRESH_TOKEN","Refresh token is invalid or expired.");db.update("update refresh_tokens set revoked_at=now() where token_hash=?",h);return session(rows.getFirst());}
 @PostMapping("/logout") @ResponseStatus(HttpStatus.NO_CONTENT) public void logout(@RequestBody Refresh r){if(r==null||r.refreshToken()==null||r.refreshToken().isBlank())return;String h=sha(r.refreshToken());var rows=db.query("select rt.user_id,mm.merchant_id from refresh_tokens rt join merchant_memberships mm on mm.user_id=rt.user_id where rt.token_hash=? and rt.revoked_at is null",(rs,i)->Map.of("user",UUID.fromString(rs.getString(1)),"merchant",UUID.fromString(rs.getString(2))),h);if(!rows.isEmpty()){db.update("update refresh_tokens set revoked_at=now() where token_hash=?",h);audit((UUID)rows.getFirst().get("user"),(UUID)rows.getFirst().get("merchant"),"merchant.logout","user",(UUID)rows.getFirst().get("user"));}}
 private Map<String,Object> session(MerchantPrincipal p){String refresh=UUID.randomUUID()+"."+UUID.randomUUID();db.update("insert into refresh_tokens(user_id,token_hash,expires_at) values(?,?,?)",p.userId(),sha(refresh),Timestamp.from(Instant.now().plus(Duration.ofDays(30))));return Map.of("access_token",tokens.issue(p,900),"refresh_token",refresh,"token_type","Bearer","merchant_id",p.merchantId());}
 private void audit(UUID user,UUID merchant,String action,String type,UUID resource){db.update("insert into audit_logs(merchant_id,actor_user_id,action,resource_type,resource_id)values(?,?,?,?,?)",merchant,user,action,type,resource);} private String required(String s){if(s==null||s.isBlank())throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_REGISTRATION","Merchant name is required.");return s;} static boolean strongPassword(String password){return password!=null&&password.length()>=12&&password.chars().anyMatch(Character::isUpperCase)&&password.chars().anyMatch(Character::isLowerCase)&&password.chars().anyMatch(Character::isDigit);} private String sha(String x){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(x.getBytes()));}catch(Exception e){throw new IllegalStateException(e);}}
}
